-- EatWell: actualizacion completa de la base original y carga del catalogo BAM.
-- Seleccionar en phpMyAdmin la base original o su copia antes de importar.
-- Este archivo no elige automaticamente una base ni reemplaza sus registros.
-- Aplicar una sola vez, con respaldo. No usar sobre la base ya actualizada.
-- Conserva la tabla historica food_scan_recipes si existe.
-- Requiere MariaDB 10.4 y permiso para crear una rutina temporal (XAMPP root).
-- Los cambios de estructura no se deshacen con ROLLBACK: conservar el respaldo.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

DROP PROCEDURE IF EXISTS eatwell_apply_initial_update;
DELIMITER $$
CREATE PROCEDURE eatwell_apply_initial_update()
BEGIN
    DECLARE module_count INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF DATABASE() IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Selecciona primero la base original o su copia en phpMyAdmin.';
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN
        ('users','recipes','exercises','food_preferences','food_scans','ai_generated_recipes',
         'favorite_recipes','personalized_recipes','user_tips')) <> 9 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La base seleccionada no tiene la estructura original de EatWell.';
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME = 'users' AND COLUMN_NAME = 'imc') <> 1
        OR (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME IN ('patient_profiles','anthropometric_measurements','clinical_histories',
        'lifestyle_goals','dietary_recalls','dietary_recall_meals',
        'food_catalog_sources','foods','nutrients','food_nutrient_values','meal_schedules','daily_meal_choices')) > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Esta base ya esta actualizada o tiene cambios parciales. No repitas la importacion.';
    END IF;
    SELECT COUNT(*) INTO module_count FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME IN ('datos_generales_paciente','mediciones_antropometricas','historial_clinico',
        'estilo_vida_metas','recordatorios_24_horas','comidas_recordatorio');
    IF module_count NOT IN (0, 6) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Los modulos del paciente estan incompletos. Revisar antes de importar.';
    END IF;
    IF EXISTS (SELECT username FROM users WHERE username IS NOT NULL GROUP BY username HAVING COUNT(*) > 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Hay usuarios repetidos. Revisarlos antes de importar.';
    END IF;
    IF EXISTS (SELECT 1 FROM ai_generated_recipes r JOIN food_scans s ON s.id = r.scan_id WHERE r.user_id <> s.user_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Hay recetas asociadas a otro propietario del analisis. Revisarlas primero.';
    END IF;



CREATE TABLE IF NOT EXISTS datos_generales_paciente (
    usuario_id INT NOT NULL,
    fecha_nacimiento DATE NULL,
    telefono VARCHAR(30) NULL,
    municipio VARCHAR(120) NULL,
    completado_en DATETIME NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (usuario_id),
    CONSTRAINT fk_datos_generales_usuario FOREIGN KEY (usuario_id)
        REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS mediciones_antropometricas (
    id INT NOT NULL AUTO_INCREMENT,
    usuario_id INT NOT NULL,
    fecha_medicion DATETIME NOT NULL,
    peso_kg DECIMAL(6,2) NOT NULL,
    estatura_cm DECIMAL(6,2) NOT NULL,
    observaciones TEXT NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    INDEX idx_mediciones_usuario_fecha (usuario_id, fecha_medicion, id),
    CONSTRAINT fk_mediciones_usuario FOREIGN KEY (usuario_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT chk_mediciones_peso CHECK (peso_kg > 0),
    CONSTRAINT chk_mediciones_estatura CHECK (estatura_cm > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS historial_clinico (
    usuario_id INT NOT NULL,
    sin_antecedentes_familiares BOOLEAN NULL,
    antecedente_familiar_diabetes BOOLEAN NULL,
    antecedente_familiar_hipertension BOOLEAN NULL,
    antecedente_familiar_obesidad BOOLEAN NULL,
    antecedente_familiar_colesterol BOOLEAN NULL,
    antecedente_familiar_cancer BOOLEAN NULL,
    antecedente_familiar_enfermedad_renal BOOLEAN NULL,
    antecedente_familiar_tiroides BOOLEAN NULL,
    sin_diagnosticos BOOLEAN NULL,
    diagnostico_diabetes BOOLEAN NULL,
    diagnostico_hipertension BOOLEAN NULL,
    diagnostico_higado_graso BOOLEAN NULL,
    diagnostico_ovario_poliquistico BOOLEAN NULL,
    diagnostico_gota BOOLEAN NULL,
    diagnostico_hipotiroidismo BOOLEAN NULL,
    sin_condiciones_bienestar BOOLEAN NULL,
    condicion_anemia BOOLEAN NULL,
    condicion_bulimia BOOLEAN NULL,
    condicion_depresion BOOLEAN NULL,
    condicion_ansiedad BOOLEAN NULL,
    otra_condicion_bienestar TEXT NULL,
    seguimiento_bienestar ENUM('no_aplica', 'no', 'actual', 'anterior') NULL,
    apoyo_profesional ENUM('no_aplica', 'no', 'actual', 'anterior') NULL,
    notas_bienestar TEXT NULL,
    sin_cirugias BOOLEAN NULL,
    cirugias TEXT NULL,
    sin_hospitalizaciones BOOLEAN NULL,
    hospitalizaciones TEXT NULL,
    embarazo_actual BOOLEAN NULL,
    lactancia_actual BOOLEAN NULL,
    ciclo_menstrual ENUM('regular', 'irregular', 'no_aplica') NULL,
    sin_alergias_alimentarias BOOLEAN NULL,
    alergias_alimentarias_json LONGTEXT NULL,
    otras_alergias_alimentarias TEXT NULL,
    sin_medicamentos BOOLEAN NULL,
    medicamentos TEXT NULL,
    sin_alergias_medicamentos BOOLEAN NULL,
    alergias_medicamentos TEXT NULL,
    sin_suplementos BOOLEAN NULL,
    suplementos TEXT NULL,
    uso_tratamiento_bajar_peso BOOLEAN NULL,
    horas_sueno ENUM('menos_de_6', '7_a_8', 'mas_de_8') NULL,
    calidad_sueno ENUM('reparador', 'no_reparador') NULL,
    frecuencia_evacuaciones ENUM('menos_de_una_al_dia', 'una_a_dos_al_dia') NULL,
    consumo_alcohol ENUM('no_consumo', 'ocasional', 'frecuente') NULL,
    consumo_tabaco BOOLEAN NULL,
    cigarrillos_al_dia SMALLINT UNSIGNED NULL,
    consumo_otras_sustancias BOOLEAN NULL,
    responsable_cocina ENUM('paciente', 'otra_persona') NULL,
    lugar_comida_habitual ENUM('casa', 'trabajo') NULL,
    apetito ENUM('normal', 'bajo', 'alto') NULL,
    ansiedad_alimentaria BOOLEAN NULL,
    agua_litros_dia DECIMAL(5,2) NULL,
    completado_en DATETIME NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (usuario_id),
    CONSTRAINT fk_historial_clinico_usuario FOREIGN KEY (usuario_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT chk_historial_alergias_json
        CHECK (alergias_alimentarias_json IS NULL OR JSON_VALID(alergias_alimentarias_json)),
    CONSTRAINT chk_historial_agua CHECK (agua_litros_dia IS NULL OR agua_litros_dia >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS estilo_vida_metas (
    usuario_id INT NOT NULL,
    objetivo ENUM('perder_grasa', 'mantener_peso', 'aumentar_masa_muscular', 'mejorar_salud') NULL,
    peso_meta_kg DECIMAL(6,2) NULL,
    nivel_actividad ENUM('sedentario', 'ligero', 'moderado', 'intenso') NULL,
    tipos_ejercicio_json LONGTEXT NULL,
    duracion_sesion_minutos SMALLINT UNSIGNED NULL,
    horario_entrenamiento ENUM('manana', 'tarde', 'noche', 'variable') NULL,
    disponibilidad_cocina ENUM('poco_tiempo', 'tiempo_medio', 'flexible') NULL,
    nivel_estres ENUM('bajo', 'moderado', 'alto') NULL,
    completado_en DATETIME NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (usuario_id),
    CONSTRAINT fk_estilo_vida_usuario FOREIGN KEY (usuario_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT chk_estilo_peso_meta CHECK (peso_meta_kg IS NULL OR peso_meta_kg > 0),
    CONSTRAINT chk_estilo_duracion CHECK (duracion_sesion_minutos IS NULL OR duracion_sesion_minutos > 0),
    CONSTRAINT chk_estilo_ejercicio_json
        CHECK (tipos_ejercicio_json IS NULL OR JSON_VALID(tipos_ejercicio_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS recordatorios_24_horas (
    id INT NOT NULL AUTO_INCREMENT,
    usuario_id INT NOT NULL,
    fecha_recordada DATE NOT NULL,
    hora_despertar TIME NULL,
    actividad_despertar TEXT NULL,
    hora_actividad_fisica TIME NULL,
    tipo_actividad_fisica VARCHAR(150) NULL,
    duracion_actividad_fisica VARCHAR(120) NULL,
    hora_dormir TIME NULL,
    observaciones TEXT NULL,
    completado_en DATETIME NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_recordatorio_usuario_fecha (usuario_id, fecha_recordada),
    CONSTRAINT fk_recordatorio_usuario FOREIGN KEY (usuario_id)
        REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comidas_recordatorio (
    id INT NOT NULL AUTO_INCREMENT,
    recordatorio_id INT NOT NULL,
    orden SMALLINT UNSIGNED NOT NULL,
    tipo_comida ENUM('desayuno', 'colacion', 'comida', 'cena', 'otra') NOT NULL,
    hora TIME NULL,
    lugar VARCHAR(150) NULL,
    alimentos_bebidas_cantidades TEXT NULL,
    comida_omitida BOOLEAN NULL,
    creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_comida_recordatorio_orden (recordatorio_id, orden),
    CONSTRAINT fk_comida_recordatorio FOREIGN KEY (recordatorio_id)
        REFERENCES recordatorios_24_horas(id) ON DELETE CASCADE,
    CONSTRAINT chk_comida_orden CHECK (orden > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE datos_generales_paciente
    DROP FOREIGN KEY fk_datos_generales_usuario,
    CHANGE COLUMN usuario_id user_id INT NOT NULL,
    CHANGE COLUMN fecha_nacimiento birth_date DATE NULL,
    CHANGE COLUMN telefono phone VARCHAR(30) NULL,
    CHANGE COLUMN municipio municipality VARCHAR(120) NULL,
    CHANGE COLUMN completado_en completed_at DATETIME NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHANGE COLUMN actualizado_en updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    ADD CONSTRAINT fk_patient_profiles_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE RESTRICT;

ALTER TABLE mediciones_antropometricas
    DROP FOREIGN KEY fk_mediciones_usuario,
    DROP CONSTRAINT chk_mediciones_peso,
    DROP CONSTRAINT chk_mediciones_estatura,
    DROP INDEX idx_mediciones_usuario_fecha,
    CHANGE COLUMN usuario_id user_id INT NOT NULL,
    CHANGE COLUMN fecha_medicion measured_at DATETIME NOT NULL,
    CHANGE COLUMN peso_kg weight_kg DECIMAL(6,2) NOT NULL,
    CHANGE COLUMN estatura_cm height_cm DECIMAL(6,2) NOT NULL,
    CHANGE COLUMN observaciones notes TEXT NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ADD INDEX idx_measurements_user_date (user_id, measured_at, id),
    ADD CONSTRAINT fk_measurements_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    ADD CONSTRAINT chk_measurements_weight CHECK (weight_kg > 0),
    ADD CONSTRAINT chk_measurements_height CHECK (height_cm > 0);

ALTER TABLE historial_clinico
    DROP FOREIGN KEY fk_historial_clinico_usuario,
    DROP CONSTRAINT chk_historial_alergias_json,
    DROP CONSTRAINT chk_historial_agua,
    CHANGE COLUMN usuario_id user_id INT NOT NULL,
    CHANGE COLUMN sin_antecedentes_familiares family_history_none BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_diabetes family_diabetes BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_hipertension family_hypertension BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_obesidad family_obesity BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_colesterol family_high_cholesterol BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_cancer family_cancer BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_enfermedad_renal family_kidney_disease BOOLEAN NULL,
    CHANGE COLUMN antecedente_familiar_tiroides family_thyroid_disease BOOLEAN NULL,
    CHANGE COLUMN sin_diagnosticos diagnoses_none BOOLEAN NULL,
    CHANGE COLUMN diagnostico_diabetes diagnosis_diabetes BOOLEAN NULL,
    CHANGE COLUMN diagnostico_hipertension diagnosis_hypertension BOOLEAN NULL,
    CHANGE COLUMN diagnostico_higado_graso diagnosis_fatty_liver BOOLEAN NULL,
    CHANGE COLUMN diagnostico_ovario_poliquistico diagnosis_pcos BOOLEAN NULL,
    CHANGE COLUMN diagnostico_gota diagnosis_gout BOOLEAN NULL,
    CHANGE COLUMN diagnostico_hipotiroidismo diagnosis_hypothyroidism BOOLEAN NULL,
    CHANGE COLUMN sin_condiciones_bienestar wellbeing_none BOOLEAN NULL,
    CHANGE COLUMN condicion_anemia wellbeing_anemia BOOLEAN NULL,
    CHANGE COLUMN condicion_bulimia wellbeing_bulimia BOOLEAN NULL,
    CHANGE COLUMN condicion_depresion wellbeing_depression BOOLEAN NULL,
    CHANGE COLUMN condicion_ansiedad wellbeing_anxiety BOOLEAN NULL,
    CHANGE COLUMN otra_condicion_bienestar wellbeing_other TEXT NULL,
    CHANGE COLUMN seguimiento_bienestar wellbeing_treatment VARCHAR(64) NULL,
    CHANGE COLUMN apoyo_profesional professional_support VARCHAR(64) NULL,
    CHANGE COLUMN notas_bienestar wellbeing_notes TEXT NULL,
    CHANGE COLUMN sin_cirugias surgeries_none BOOLEAN NULL,
    CHANGE COLUMN cirugias surgeries TEXT NULL,
    CHANGE COLUMN sin_hospitalizaciones hospitalizations_none BOOLEAN NULL,
    CHANGE COLUMN hospitalizaciones hospitalizations TEXT NULL,
    CHANGE COLUMN embarazo_actual pregnant BOOLEAN NULL,
    CHANGE COLUMN lactancia_actual lactating BOOLEAN NULL,
    CHANGE COLUMN ciclo_menstrual menstrual_cycle VARCHAR(64) NULL,
    CHANGE COLUMN sin_alergias_alimentarias food_allergies_none BOOLEAN NULL,
    CHANGE COLUMN alergias_alimentarias_json food_allergies_json LONGTEXT NULL,
    CHANGE COLUMN otras_alergias_alimentarias other_food_allergies TEXT NULL,
    CHANGE COLUMN sin_medicamentos medications_none BOOLEAN NULL,
    CHANGE COLUMN medicamentos medications TEXT NULL,
    CHANGE COLUMN sin_alergias_medicamentos medication_allergies_none BOOLEAN NULL,
    CHANGE COLUMN alergias_medicamentos medication_allergies TEXT NULL,
    CHANGE COLUMN sin_suplementos supplements_none BOOLEAN NULL,
    CHANGE COLUMN suplementos supplements TEXT NULL,
    CHANGE COLUMN uso_tratamiento_bajar_peso weight_loss_treatment BOOLEAN NULL,
    CHANGE COLUMN horas_sueno sleep_hours VARCHAR(64) NULL,
    CHANGE COLUMN calidad_sueno sleep_quality VARCHAR(64) NULL,
    CHANGE COLUMN frecuencia_evacuaciones bowel_frequency VARCHAR(64) NULL,
    CHANGE COLUMN consumo_alcohol alcohol_use VARCHAR(64) NULL,
    CHANGE COLUMN consumo_tabaco tobacco_use BOOLEAN NULL,
    CHANGE COLUMN cigarrillos_al_dia cigarettes_per_day SMALLINT UNSIGNED NULL,
    CHANGE COLUMN consumo_otras_sustancias other_substance_use BOOLEAN NULL,
    CHANGE COLUMN responsable_cocina cooking_responsibility VARCHAR(64) NULL,
    CHANGE COLUMN lugar_comida_habitual usual_eating_place VARCHAR(64) NULL,
    CHANGE COLUMN apetito appetite VARCHAR(64) NULL,
    CHANGE COLUMN ansiedad_alimentaria eating_anxiety BOOLEAN NULL,
    CHANGE COLUMN agua_litros_dia daily_water_liters DECIMAL(5,2) NULL,
    CHANGE COLUMN completado_en completed_at DATETIME NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHANGE COLUMN actualizado_en updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    ADD CONSTRAINT fk_clinical_histories_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    ADD CONSTRAINT chk_clinical_food_allergies_json
        CHECK (food_allergies_json IS NULL OR JSON_VALID(food_allergies_json)),
    ADD CONSTRAINT chk_clinical_water CHECK (daily_water_liters IS NULL OR daily_water_liters >= 0),
    ADD CONSTRAINT chk_clinical_boolean_answers CHECK ((family_history_none IS NULL OR family_history_none IN (0, 1)) AND (family_diabetes IS NULL OR family_diabetes IN (0, 1)) AND (family_hypertension IS NULL OR family_hypertension IN (0, 1)) AND (family_obesity IS NULL OR family_obesity IN (0, 1)) AND (family_high_cholesterol IS NULL OR family_high_cholesterol IN (0, 1)) AND (family_cancer IS NULL OR family_cancer IN (0, 1)) AND (family_kidney_disease IS NULL OR family_kidney_disease IN (0, 1)) AND (family_thyroid_disease IS NULL OR family_thyroid_disease IN (0, 1)) AND (diagnoses_none IS NULL OR diagnoses_none IN (0, 1)) AND (diagnosis_diabetes IS NULL OR diagnosis_diabetes IN (0, 1)) AND (diagnosis_hypertension IS NULL OR diagnosis_hypertension IN (0, 1)) AND (diagnosis_fatty_liver IS NULL OR diagnosis_fatty_liver IN (0, 1)) AND (diagnosis_pcos IS NULL OR diagnosis_pcos IN (0, 1)) AND (diagnosis_gout IS NULL OR diagnosis_gout IN (0, 1)) AND (diagnosis_hypothyroidism IS NULL OR diagnosis_hypothyroidism IN (0, 1)) AND (wellbeing_none IS NULL OR wellbeing_none IN (0, 1)) AND (wellbeing_anemia IS NULL OR wellbeing_anemia IN (0, 1)) AND (wellbeing_bulimia IS NULL OR wellbeing_bulimia IN (0, 1)) AND (wellbeing_depression IS NULL OR wellbeing_depression IN (0, 1)) AND (wellbeing_anxiety IS NULL OR wellbeing_anxiety IN (0, 1)) AND (surgeries_none IS NULL OR surgeries_none IN (0, 1)) AND (hospitalizations_none IS NULL OR hospitalizations_none IN (0, 1)) AND (pregnant IS NULL OR pregnant IN (0, 1)) AND (lactating IS NULL OR lactating IN (0, 1)) AND (food_allergies_none IS NULL OR food_allergies_none IN (0, 1)) AND (medications_none IS NULL OR medications_none IN (0, 1)) AND (medication_allergies_none IS NULL OR medication_allergies_none IN (0, 1)) AND (supplements_none IS NULL OR supplements_none IN (0, 1)) AND (weight_loss_treatment IS NULL OR weight_loss_treatment IN (0, 1)) AND (tobacco_use IS NULL OR tobacco_use IN (0, 1)) AND (other_substance_use IS NULL OR other_substance_use IN (0, 1)) AND (eating_anxiety IS NULL OR eating_anxiety IN (0, 1)));

UPDATE historial_clinico SET
    wellbeing_treatment = CASE wellbeing_treatment WHEN 'no_aplica' THEN 'not_applicable' WHEN 'no' THEN 'no' WHEN 'actual' THEN 'current' WHEN 'anterior' THEN 'previous' ELSE wellbeing_treatment END,
    professional_support = CASE professional_support WHEN 'no_aplica' THEN 'not_applicable' WHEN 'no' THEN 'no' WHEN 'actual' THEN 'current' WHEN 'anterior' THEN 'previous' ELSE professional_support END,
    menstrual_cycle = CASE menstrual_cycle WHEN 'regular' THEN 'regular' WHEN 'irregular' THEN 'irregular' WHEN 'no_aplica' THEN 'not_applicable' ELSE menstrual_cycle END,
    sleep_hours = CASE sleep_hours WHEN 'menos_de_6' THEN 'under_6' WHEN '7_a_8' THEN '7_to_8' WHEN 'mas_de_8' THEN 'over_8' ELSE sleep_hours END,
    sleep_quality = CASE sleep_quality WHEN 'reparador' THEN 'restful' WHEN 'no_reparador' THEN 'not_restful' ELSE sleep_quality END,
    bowel_frequency = CASE bowel_frequency WHEN 'menos_de_una_al_dia' THEN 'less_than_once_daily' WHEN 'una_a_dos_al_dia' THEN 'once_or_twice_daily' ELSE bowel_frequency END,
    alcohol_use = CASE alcohol_use WHEN 'no_consumo' THEN 'none' WHEN 'ocasional' THEN 'occasional' WHEN 'frecuente' THEN 'frequent' ELSE alcohol_use END,
    cooking_responsibility = CASE cooking_responsibility WHEN 'paciente' THEN 'patient' WHEN 'otra_persona' THEN 'other_person' ELSE cooking_responsibility END,
    usual_eating_place = CASE usual_eating_place WHEN 'casa' THEN 'home' WHEN 'trabajo' THEN 'work' ELSE usual_eating_place END,
    appetite = CASE appetite WHEN 'normal' THEN 'normal' WHEN 'bajo' THEN 'low' WHEN 'alto' THEN 'high' ELSE appetite END,
    updated_at = updated_at;

ALTER TABLE historial_clinico
    MODIFY COLUMN wellbeing_treatment ENUM('not_applicable', 'no', 'current', 'previous') NULL,
    MODIFY COLUMN professional_support ENUM('not_applicable', 'no', 'current', 'previous') NULL,
    MODIFY COLUMN menstrual_cycle ENUM('regular', 'irregular', 'not_applicable') NULL,
    MODIFY COLUMN sleep_hours ENUM('under_6', '7_to_8', 'over_8') NULL,
    MODIFY COLUMN sleep_quality ENUM('restful', 'not_restful') NULL,
    MODIFY COLUMN bowel_frequency ENUM('less_than_once_daily', 'once_or_twice_daily') NULL,
    MODIFY COLUMN alcohol_use ENUM('none', 'occasional', 'frequent') NULL,
    MODIFY COLUMN cooking_responsibility ENUM('patient', 'other_person') NULL,
    MODIFY COLUMN usual_eating_place ENUM('home', 'work') NULL,
    MODIFY COLUMN appetite ENUM('normal', 'low', 'high') NULL;

ALTER TABLE estilo_vida_metas
    DROP FOREIGN KEY fk_estilo_vida_usuario,
    DROP CONSTRAINT chk_estilo_peso_meta,
    DROP CONSTRAINT chk_estilo_duracion,
    DROP CONSTRAINT chk_estilo_ejercicio_json,
    CHANGE COLUMN usuario_id user_id INT NOT NULL,
    CHANGE COLUMN objetivo goal VARCHAR(64) NULL,
    CHANGE COLUMN peso_meta_kg target_weight_kg DECIMAL(6,2) NULL,
    CHANGE COLUMN nivel_actividad activity_level VARCHAR(64) NULL,
    CHANGE COLUMN tipos_ejercicio_json exercise_types_json LONGTEXT NULL,
    CHANGE COLUMN duracion_sesion_minutos session_duration_minutes SMALLINT UNSIGNED NULL,
    CHANGE COLUMN horario_entrenamiento training_time VARCHAR(64) NULL,
    CHANGE COLUMN disponibilidad_cocina cooking_availability VARCHAR(64) NULL,
    CHANGE COLUMN nivel_estres stress_level VARCHAR(64) NULL,
    CHANGE COLUMN completado_en completed_at DATETIME NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHANGE COLUMN actualizado_en updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    ADD CONSTRAINT fk_lifestyle_goals_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE RESTRICT,
    ADD CONSTRAINT chk_lifestyle_target_weight CHECK (target_weight_kg IS NULL OR target_weight_kg > 0),
    ADD CONSTRAINT chk_lifestyle_session_duration CHECK (session_duration_minutes IS NULL OR session_duration_minutes > 0),
    ADD CONSTRAINT chk_lifestyle_exercise_json
        CHECK (exercise_types_json IS NULL OR JSON_VALID(exercise_types_json));

UPDATE estilo_vida_metas SET
    goal = CASE goal WHEN 'perder_grasa' THEN 'lose_weight' WHEN 'mantener_peso' THEN 'maintain' WHEN 'aumentar_masa_muscular' THEN 'gain_muscle' WHEN 'mejorar_salud' THEN 'improve_health' ELSE goal END,
    activity_level = CASE activity_level WHEN 'sedentario' THEN 'sedentary' WHEN 'ligero' THEN 'light' WHEN 'moderado' THEN 'moderate' WHEN 'intenso' THEN 'intense' ELSE activity_level END,
    training_time = CASE training_time WHEN 'manana' THEN 'morning' WHEN 'tarde' THEN 'afternoon' WHEN 'noche' THEN 'evening' WHEN 'variable' THEN 'variable' ELSE training_time END,
    cooking_availability = CASE cooking_availability WHEN 'poco_tiempo' THEN 'short' WHEN 'tiempo_medio' THEN 'medium' WHEN 'flexible' THEN 'flexible' ELSE cooking_availability END,
    stress_level = CASE stress_level WHEN 'bajo' THEN 'low' WHEN 'moderado' THEN 'moderate' WHEN 'alto' THEN 'high' ELSE stress_level END,
    updated_at = updated_at;

ALTER TABLE estilo_vida_metas
    MODIFY COLUMN goal ENUM('lose_weight', 'maintain', 'gain_muscle', 'improve_health') NULL,
    MODIFY COLUMN activity_level ENUM('sedentary', 'light', 'moderate', 'intense') NULL,
    MODIFY COLUMN training_time ENUM('morning', 'afternoon', 'evening', 'variable') NULL,
    MODIFY COLUMN cooking_availability ENUM('short', 'medium', 'flexible') NULL,
    MODIFY COLUMN stress_level ENUM('low', 'moderate', 'high') NULL;

ALTER TABLE recordatorios_24_horas
    DROP FOREIGN KEY fk_recordatorio_usuario,
    DROP INDEX uq_recordatorio_usuario_fecha,
    CHANGE COLUMN usuario_id user_id INT NOT NULL,
    CHANGE COLUMN fecha_recordada recall_date DATE NOT NULL,
    CHANGE COLUMN hora_despertar wake_time TIME NULL,
    CHANGE COLUMN actividad_despertar wake_activity TEXT NULL,
    CHANGE COLUMN hora_actividad_fisica exercise_time TIME NULL,
    CHANGE COLUMN tipo_actividad_fisica exercise_type VARCHAR(150) NULL,
    CHANGE COLUMN duracion_actividad_fisica exercise_duration VARCHAR(120) NULL,
    CHANGE COLUMN hora_dormir sleep_time TIME NULL,
    CHANGE COLUMN observaciones notes TEXT NULL,
    CHANGE COLUMN completado_en completed_at DATETIME NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHANGE COLUMN actualizado_en updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    ADD UNIQUE KEY uq_dietary_recalls_user_date (user_id, recall_date),
    ADD CONSTRAINT fk_dietary_recalls_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE RESTRICT;

ALTER TABLE comidas_recordatorio
    DROP FOREIGN KEY fk_comida_recordatorio,
    DROP CONSTRAINT chk_comida_orden,
    DROP INDEX uq_comida_recordatorio_orden,
    CHANGE COLUMN recordatorio_id recall_id INT NOT NULL,
    CHANGE COLUMN orden position SMALLINT UNSIGNED NOT NULL,
    CHANGE COLUMN tipo_comida meal_type VARCHAR(64) NULL,
    CHANGE COLUMN hora meal_time TIME NULL,
    CHANGE COLUMN lugar location VARCHAR(150) NULL,
    CHANGE COLUMN alimentos_bebidas_cantidades food_drink_quantities TEXT NULL,
    CHANGE COLUMN comida_omitida skipped BOOLEAN NULL,
    CHANGE COLUMN creado_en created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHANGE COLUMN actualizado_en updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    ADD UNIQUE KEY uq_recall_meals_position (recall_id, position),
    ADD CONSTRAINT fk_recall_meals_recall FOREIGN KEY (recall_id)
        REFERENCES recordatorios_24_horas(id) ON DELETE CASCADE,
    ADD CONSTRAINT chk_recall_meals_position CHECK (position > 0),
    ADD CONSTRAINT chk_recall_meals_skipped CHECK ((skipped IS NULL OR skipped IN (0, 1)));

UPDATE comidas_recordatorio SET
    meal_type = CASE meal_type WHEN 'desayuno' THEN 'breakfast' WHEN 'colacion' THEN 'snack' WHEN 'comida' THEN 'lunch' WHEN 'cena' THEN 'dinner' WHEN 'otra' THEN 'other' ELSE meal_type END,
    updated_at = updated_at;

ALTER TABLE comidas_recordatorio
    MODIFY COLUMN meal_type ENUM('breakfast', 'snack', 'lunch', 'dinner', 'other') NOT NULL;

RENAME TABLE
    datos_generales_paciente TO patient_profiles,
    mediciones_antropometricas TO anthropometric_measurements,
    historial_clinico TO clinical_histories,
    estilo_vida_metas TO lifestyle_goals,
    recordatorios_24_horas TO dietary_recalls,
    comidas_recordatorio TO dietary_recall_meals;


